import type { OxlintOverride } from 'vite-plus/lint';

import { fmtConfig, restrictedImportsOverride } from '@sandrinodm/oxlint-config';
import oxlintConfig from '@sandrinodm/oxlint-config/effect';
import { defineConfig } from 'vite-plus';

/**
 * Generated, vendored or published output that neither the formatter nor the linter should touch.
 */
const IGNORED = [
  // Template, mockup and fixture workspaces are author-facing Markdown, YAML and HTML, kept as written.
  'apps/cli/templates/**',
  'packages/test-fixtures/atlas/**',
  // Generated by `pnpm reference`.
  'docs/reference.md',
  'docs/schemas/**',
  'apps/cli/lib/**',
  'dist/**',
  'pnpm-lock.yaml',
  '**/node_modules/**',
  'apps/cli/.roadmark-package-*/**',
  // Parallel work-package checkouts (git worktrees).
  '.worktrees/**',
  // Claude Code agent worktrees and local settings.
  '.claude/**',
  // e2e run output: reports, traces, app logs and the built Atlas site.
  '**/.e2e/**',
];

/**
 * Specifiers of the Node platform package, which only the compiler's platform module may import.
 */
const PLATFORM_NODE = {
  group: ['@effect/platform-node', '@effect/platform-node/*'],
  message:
    'Import Node platform services from @roadmark/compiler/platform, which the package bundles.',
};

/**
 * The CLI package, which the compiler, the renderer's sources and the renderer's browser suites
 * must not import: the suites run the CLI as a process (packages/web/e2e/support/cli.ts), so
 * @roadmark/web never depends on the package that depends on it.
 */
const CLI = {
  group: ['roadmark', 'roadmark/**'],
  message: 'The compiler and renderer sit below the CLI and never import it.',
};

/**
 * The renderer package, which the compiler must not depend on.
 */
const WEB = {
  group: ['@roadmark/web', '@roadmark/web/**'],
  message: 'The compiler produces the model the renderer reads; it never renders.',
};

/**
 * Node built-ins, banned in renderers that build strings from compiled data.
 */
const NODE = {
  group: ['node:*', 'node:*/*'],
  message:
    'Site renderers build strings from compiled data; only the files that read assets or run esbuild may use Node.',
};

/**
 * Repository layout rules layered on the shared preset. A later override replaces the restricted
 * imports of an earlier one for the files both match, so each one lists every ban that applies.
 */
const LAYOUT_OVERRIDES: Array<OxlintOverride> = [
  {
    // The dependency graph resolver keeps its traversal, cycle detection and reporting together on
    // purpose: splitting it would scatter one algorithm across files without making any part simpler.
    files: ['packages/compiler/src/graph.ts'],
    rules: { 'eslint/max-lines': 'off' },
  },
  {
    // Browser and filesystem test steps drive one page or one directory in order; running them
    // concurrently would race on shared state.
    files: ['**/*.test.ts', 'packages/web/e2e/**/*.ts', '**/scripts/**/*.ts'],
    rules: { 'eslint/no-await-in-loop': 'off' },
  },
  {
    // A browser suite is one describe callback holding its tests, as the node:test suites were; the
    // preset lifts these limits for *.test.ts files only.
    files: ['packages/web/e2e/*.e2e.ts'],
    rules: { 'eslint/max-lines': 'off', 'eslint/max-lines-per-function': 'off' },
  },
  {
    // node:test has no Effect integration (unlike `it.effect` in @effect/vitest), so tests run
    // effects directly.
    files: ['**/*.test.ts'],
    rules: { 'slop/no-effect-run-outside-entry': 'off' },
  },
  {
    // The CLI writes results and JSON reports to stdout by design.
    files: ['apps/cli/src/**/*.ts', '**/scripts/**/*.ts'],
    rules: { 'no-console': 'off' },
  },
  // The package build bundles the compiler's platform module so installs skip
  // @effect/platform-node and its required Redis peer. Importing the package anywhere else would
  // bring it back.
  restrictedImportsOverride(['**/*.ts'], [PLATFORM_NODE]),
  restrictedImportsOverride(['packages/compiler/**/*.ts'], [PLATFORM_NODE, WEB, CLI]),
  restrictedImportsOverride(['packages/compiler/src/platform.ts'], [WEB, CLI]),
  restrictedImportsOverride(['packages/web/src/**/*.ts'], [PLATFORM_NODE, CLI, NODE]),
  // The browser suites and their config drive the CLI as a process, never as a dependency.
  restrictedImportsOverride(
    ['packages/web/e2e/**/*.ts', 'packages/web/e2e.config.ts'],
    [PLATFORM_NODE, CLI],
  ),
  // render.ts reads the bundled stylesheet and font, and client-bundle.ts runs esbuild and reads
  // the prebuilt bundle: both are build steps, not renderers, so they need the filesystem. Tests
  // create fixture workspaces on disk.
  restrictedImportsOverride(
    [
      'packages/web/src/render.ts',
      'packages/web/src/client-bundle.ts',
      'packages/web/src/**/*.test.ts',
    ],
    [PLATFORM_NODE, CLI],
  ),
  restrictedImportsOverride(
    ['packages/web/src/client/**/*.ts'],
    [
      CLI,
      {
        group: ['node:*', 'node:*/*', 'effect', 'effect/*', '@effect/*', '@roadmark/**'],
        message:
          'Browser enhancement code runs in the page: no Node built-ins, no Effect runtime and no server-side packages.',
      },
    ],
  ),
  // The browser modules' unit tests and their DOM helper run in Node: they read the Atlas fixture,
  // render it with the compiler and renderer, and register happy-dom's globals.
  restrictedImportsOverride(
    ['packages/web/src/client/**/*.test.ts', 'packages/web/src/client/test-dom.ts'],
    [PLATFORM_NODE, CLI],
  ),
  {
    files: ['packages/web/src/client/**/*.ts'],
    env: { browser: true },
  },
];

export default defineConfig({
  staged: {
    '*': 'effect-tsgo vp check --fix',
  },
  fmt: {
    ...fmtConfig,
    ignorePatterns: [
      ...fmtConfig.ignorePatterns,
      ...IGNORED,
      // Hand-written prose, kept exactly as authored.
      'docs/**',
    ],
  },
  lint: {
    ...oxlintConfig,
    ignorePatterns: [...oxlintConfig.ignorePatterns, ...IGNORED],
    rules: {
      ...oxlintConfig.rules,
      // effect/cli and effect/http are marked unstable in Effect 4.1; this CLI depends on them by design.
      'effecttsgo/unstable-api-usage': 'off',
      'effecttsgo/experimental-api-usage': 'off',
    },
    overrides: [...oxlintConfig.overrides, ...LAYOUT_OVERRIDES],
  },
  check: {
    fmt: true,
    lint: true,
  },
  run: {
    cache: {
      tasks: true,
      scripts: false,
    },
    tasks: {
      check: {
        command: 'effect-tsgo vp check',
        cache: {
          input: [{ auto: true }, '!**/dist/**', '!**/lib/**'],
        },
      },
    },
  },
});
